  if(o.r!==undefined) f.cornerRadius=o.r;
  if(o.stroke){ f.strokes=solid(o.stroke); f.strokeWeight=o.sw||1; }
  if(o.mode){ f.layoutMode=o.mode; f.primaryAxisSizingMode=o.prim||'FIXED'; f.counterAxisSizingMode=o.cnt||'FIXED'; f.itemSpacing=o.gap||0;
